mapper.select:
select u.USER_ID, u.DEPT_ID, u.NICK_NAME, u.USER_NAME, u.EMAIL, u.AVATAR, u.PHONENUMBER, u.SEX, u.STATUS, u.DEL_FLAG, u.LOGIN_IP, u.LOGIN_DATE, u.CREATE_BY, u.CREATE_TIME, u.REMARK, d.DEPT_NAME, d.LEADER from SYS_USER u
left join SYS_DEPT d on u.DEPT_ID = d.DEPT_ID
where u.DEL_FLAG = '0'

	AND u.USER_ID = #{userId}


	AND u.USER_NAME like concat('%', #{userName}, '%')


	AND u.STATUS = #{status}


	AND u.PHONENUMBER like concat('%', #{phonenumber}, '%')


	AND u.CREATE_TIME >= to_date(#{params.beginTime},'yyyy-MM-dd')


	AND u.CREATE_TIME <= to_date(#{params.endTime},'yyyy-MM-dd')


	AND (u.DEPT_ID in (SELECT DEPT_ID
	FROM SYS_DEPT
	START WITH PARENT_ID = #{deptId}
	OR DEPT_ID = #{deptId}
	CONNECT BY PARENT_ID = PRIOR DEPT_ID) )


${params.dataScope}

select distinct u.USER_ID, u.DEPT_ID, u.USER_NAME, u.NICK_NAME, u.EMAIL, u.PHONENUMBER, u.STATUS, u.CREATE_TIME from SYS_USER u left join SYS_DEPT d on u.DEPT_ID = d.DEPT_ID left join SYS_USER_ROLE ur on u.USER_ID = ur.USER_ID left join SYS_ROLE r on r.ROLE_ID = ur.ROLE_ID where u.DEL_FLAG = '0' and r.ROLE_ID = #{roleId}
AND u.USER_NAME like concat('%', #{userName}, '%')
AND u.PHONENUMBER like concat('%', #{phonenumber}, '%')
${params.dataScope}

mapper.update:
update SYS_USER
DEPT_ID = #{deptId}, USER_NAME = #{userName}, NICK_NAME = #{nickName}, EMAIL = #{email}, PHONENUMBER = #{phonenumber}, SEX = #{sex}, AVATAR = #{avatar}, PASSWORD = #{password}, STATUS = #{status}, LOGIN_IP = #{loginIp}, LOGIN_DATE = #{loginDate}, UPDATE_BY = #{updateBy}, REMARK = #{remark}, UPDATE_TIME = CURRENT_TIMESTAMP
where USER_ID = #{userId}
